const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=n=>'<svg class="ico" aria-hidden="true"><use href="#'+n+'"/></svg>';
const colors=['#ebecf0','#c6e8db','#79d2ad','#36b37e','#00875a'];
let profile=location.hash==='#organization'?'org':'user',tab='overview',year=2026,viewer='public',avatarMode='gravatar',filter='all',day='',expanded=false,readmeMode='present';
const watching=new Set(),stars=new Set();
function avatar(seed=0,org=false){
if(org)return '<svg viewBox="0 0 80 80" role="img" aria-label="Mercury Labs logo"><rect width="80" height="80" fill="#deebff"/><g transform="translate(15 12) scale(2.1)" fill="none" stroke="#0052cc" stroke-width="1.6" stroke-linejoin="round"><path d="M8 3h8M9 3v7L4 20h16l-5-10V3M7 15h10M9 18h1m3-1h1"/></g></svg>';
if(avatarMode==='fallback')return ['PR','MC','AS','JL'][seed%4];
if(avatarMode==='upload')return '<svg viewBox="0 0 80 80" role="img" aria-label="Sample uploaded avatar"><rect width="80" height="80" fill="#c1e7e3"/><path d="M10 80a30 30 0 0 1 60 0" fill="#0747a6"/><circle cx="40" cy="33" r="18" fill="#e7b38c"/><path d="M22 30c-4-29 41-28 36 2L46 20 24 30" fill="#253858"/><circle cx="34" cy="34" r="1.5"/><circle cx="46" cy="34" r="1.5"/><path d="M35 43q5 4 10 0" stroke="#824f3b" fill="none" stroke-width="2"/></svg>';
return '<svg viewBox="0 0 80 80" role="img" aria-label="Sample Gravatar identicon"><rect width="80" height="80" fill="#eaf3f8"/><g fill="'+['#008da6','#6554c0','#006644','#de350b'][seed%4]+'"><path d="M16 16h16v16H16zm32 0h16v16H48zM32 32h16v16H32zM16 48h16v16H16zm32 0h16v16H48z"/><path d="M32 16h16v8H32zM32 56h16v8H32z" opacity=".4"/></g></svg>';
}
const data={user:{name:'Patrick Raynor',handle:'raynorpat',bio:'Building useful tools, one changeset at a time.',place:'United States',joined:'Joined October 2020',repo:'raynorpat/raynorpat',path:'README.md'},org:{name:'Mercury Labs',handle:'mercury-labs',bio:'Small tools. Shared knowledge. Open collaboration.',place:'Distributed team',joined:'Established 2023',repo:'mercury-labs/.github',path:'profile/README.md'}};
const memberProfiles=[data.user,{name:'Morgan Chen',handle:'morgan-chen',bio:'Making developer tools more approachable.',place:'Distributed team',joined:'Joined March 2023',repo:'morgan-chen/morgan-chen',path:'README.md'},{name:'Alex Stone',handle:'alex-stone',bio:'Reliable infrastructure and thoughtful code review.',place:'Distributed team',joined:'Joined June 2023',repo:'alex-stone/alex-stone',path:'README.md'},{name:'Jamie Lee',handle:'jamie-lee',bio:'Working on documentation and the little details.',place:'Distributed team',joined:'Joined January 2024',repo:'jamie-lee/jamie-lee',path:'README.md'}];
let selectedPerson=Math.max(0,memberProfiles.findIndex(p=>location.hash==='#user/'+p.handle));
data.user=memberProfiles[selectedPerson];
$('#rail').innerHTML=[['beaker','Hgs home'],['search','Search'],['compass','Explore repositories'],['clock','Recents'],['plus','Create repository']].map(([i,l])=>'<button class="'+(i==='beaker'?'mark':'')+'" data-demo="'+l+'" aria-label="'+l+'">'+icon(i)+'</button>').join('')+'<div class="spacer"></div><button data-demo="Administration" aria-label="Administration">'+icon('gear')+'</button><button data-help="true" aria-label="Help">'+icon('help')+'</button><button data-demo="Account" aria-label="Account"><span class="avatar" id="rail-avatar"></span></button>';
$('#workspace-nav').innerHTML=[['grid','Overview','data-demo="Workspace overview"'],['repo','Repositories','data-tab="repositories"'],['people','Organizations','data-profile="org"'],['pull','Pull requests','data-demo="Pull requests"'],['issue','Issues','data-demo="Issues"']].map(([i,l,a])=>'<button class="navitem" '+a+'>'+icon(i)+l+'</button>').join('');
function repos(){const owner=data[profile].handle;return [{name:profile==='user'?'Hgs':'mercurial-service',owner,description:'A painless, self-hosted Mercurial service. Built with Go.',language:'Go',stars:24,watch:8},{name:profile==='user'?'backup-dashboard':'hg-toolkit',owner,description:profile==='user'?'A clear view of backups, health checks and recovery.':'Practical tools for working with changesets and bookmarks.',language:profile==='user'?'TypeScript':'Go',stars:12,watch:4},{name:profile==='user'?data.user.handle:'.github',owner,description:'A little about the people behind the repositories.',language:'Markdown',stars:3,watch:2},...(viewer==='member'?[{name:'release-planning',owner,description:'Internal release notes and planning.',language:'Markdown',stars:2,watch:3,private:true}]:[])]}
function repoRows(limit=99){return repos().slice(0,limit).map(r=>'<div class="repo-row">'+icon('repo')+'<div><button class="link repo-name" data-repo="'+r.name+'">'+r.name+'</button><span class="badge">'+(r.private?'Private':'Public')+'</span><p>'+r.description+'</p><div class="repo-foot"><span><i class="dot" style="background:'+(r.language==='Go'?'#00a3bf':r.language==='Markdown'?'#6554c0':'#3178c6')+'"></i>'+r.language+'</span><span>Updated Oct 26</span></div></div><div class="repo-actions"><button class="tiny" data-watch="'+r.name+'" aria-pressed="'+watching.has(r.name)+'">'+(watching.has(r.name)?'Watching':'Watch')+' '+(r.watch+(watching.has(r.name)?1:0))+'</button><button class="tiny" data-star="'+r.name+'" aria-pressed="'+stars.has(r.name)+'">'+(stars.has(r.name)?'★ Starred':'☆ Star')+' '+(r.stars+(stars.has(r.name)?1:0))+'</button></div></div>').join('')}
function people(){return ['Patrick Raynor','Morgan Chen','Alex Stone','Jamie Lee'].map((name,i)=>'<button class="person-row person-link" data-person="'+i+'" aria-label="View '+name+' profile"><span class="avatar">'+avatar(i)+'</span><span><b>'+name+'</b><small>'+(i===0?'Maintainer':'Contributor')+'</small></span></button>').join('')}
function side(){return '<aside class="aside-info"><section class="side-section"><h3>'+(profile==='user'?'Organizations':'People')+'</h3>'+(profile==='user'?'<button class="link person-row" data-profile="org"><span class="avatar">'+avatar(0,true)+'</span>Mercury Labs</button><p>Making Mercurial hosting feel at home.</p>':people()+'<button class="link" data-tab="people">View people →</button>')+'</section><section class="side-section"><h3>'+(profile==='user'?'About this activity':'Organization activity')+'</h3><p>'+(profile==='user'?'Changesets, issues, pull requests and reviews across visible repositories.':'Contributions to Mercury Labs repositories, grouped across its contributors.')+'</p><p>'+(viewer==='public'?'Showing public repositories only.':'Showing repositories this member can access.')+'</p><button class="link" data-help="true">How contributions are counted</button></section></aside>'}
function days(){let start=Date.UTC(year,0,1),end=year===2026?Date.UTC(2026,9,26):Date.UTC(year,11,31),arr=[];for(let t=start,i=0;t<=end;t+=86400000,i++){let d=new Date(t),seed=(i*31+year*7+(profile==='org'?17:0))%113,n=seed%6===0||d.getUTCDay()===0?0:seed%11;if(profile==='org')n*=3;arr.push({date:d.toISOString().slice(0,10),n:n+(viewer==='member'&&i%9===0?3:0),weekday:d.getUTCDay()})}return arr}
function totals(){const n=days().reduce((s,d)=>s+d.n,0),c=Math.floor(n*.72),p=Math.floor(n*.12),i=Math.floor(n*.09);return {total:n,changesets:c,pulls:p,issues:i,reviews:n-c-p-i}}
function calendar(){let ds=days(),offset=new Date(Date.UTC(year,0,1)).getUTCDay(),cells='',months='',lastMonth=-1;ds.forEach((d,i)=>{let x=42+Math.floor((i+offset)/7)*13,y=26+d.weekday*13,level=d.n===0?0:Math.min(4,Math.ceil(d.n/(profile==='org'?8:3))),month=Number(d.date.slice(5,7))-1;if(month!==lastMonth){months+='<text x="'+x+'" y="13">'+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][month]+'</text>';lastMonth=month}cells+='<rect data-day="'+d.date+'" x="'+x+'" y="'+y+'" width="10" height="10" rx="2" fill="'+colors[level]+'" '+(day===d.date?'stroke="#172b4d" stroke-width="2"':'')+'><title>'+d.date+': '+d.n+' contributions</title></rect>'});const t=totals(),selected=ds.find(d=>d.date===day);return '<div class="section-heading"><h2>'+t.total.toLocaleString()+' contributions in '+year+'</h2><label class="subtle">Year <select id="year" class="year-select">'+[2026,2025,2024].map(y=>'<option '+(year===y?'selected':'')+'>'+y+'</option>').join('')+'</select></label></div><div class="calendar-box"><div class="calendar-wrap"><svg viewBox="0 0 735 125" role="img" aria-label="'+year+' contribution calendar. Use the date field below for accessible daily counts."><g font-size="10" fill="#5e6c84">'+months+'<text x="0" y="47">Mon</text><text x="0" y="73">Wed</text><text x="0" y="99">Fri</text></g>'+cells+'</svg></div><div class="calendar-key">Less '+colors.map(c=>'<i class="swatch" style="background:'+c+'"></i>').join('')+' More</div><div class="selection"><span id="day-summary" aria-live="polite">'+(selected?selected.n+' contributions on '+selected.date:'Select a day to explore its contributions.')+'</span><label>Day <input id="day-picker" type="date" min="'+year+'-01-01" max="'+(year===2026?'2026-10-26':year+'-12-31')+'" value="'+day+'"></label>'+(day?'<button class="link" id="clear-day">Clear</button>':'')+'</div><div class="metrics">'+[['changesets','Changesets'],['pulls','Pull requests'],['issues','Issues'],['reviews','Reviews']].map(([k,l])=>'<div class="metric"><strong>'+t[k].toLocaleString()+'</strong><span>'+l+' · '+Math.round(t[k]/t.total*100)+'%</span><i style="width:'+Math.max(9,t[k]/t.total*100)+'%"></i></div>').join('')+'</div></div>'}
function timeline(){let owner=data[profile].handle,repo=profile==='user'?'Hgs':'mercurial-service';let events=[{kind:'changesets',icon:'changeset',title:(profile==='org'?'4 contributors created':'Created')+' '+(year===2026?'86':'64')+' changesets in 2 repositories',body:'<div class="event-line"><button class="link" data-repo="'+repo+'">'+owner+'/'+repo+'</button><span class="subtle">'+(year===2026?'64':'48')+' changesets</span><span class="bar" style="width:28%"></span></div><div class="event-line"><button class="link" data-repo="hg-toolkit">'+owner+'/'+(profile==='user'?'backup-dashboard':'hg-toolkit')+'</button><span class="subtle">'+(year===2026?'22':'16')+' changesets</span><span class="bar" style="width:10%"></span></div>'},{kind:'pulls',icon:'pull',title:profile==='org'?'Merged 6 pull requests from 3 contributors':'Opened 6 pull requests in 2 repositories',body:'<div class="event-card"><span class="event-state purple">Merged</span> <button class="link" data-detail="pull">Improve repository browsing on small screens</button><p>'+owner+'/'+repo+' · #42 · feature/responsive-source → default</p></div>'},{kind:'reviews',icon:'check',title:profile==='org'?'3 members reviewed 8 pull requests':'Reviewed 8 pull requests',body:'<div class="event-line"><span>'+owner+'/'+repo+'</span><span class="event-state">6 approved</span></div><p class="subtle">Feedback on repository navigation and readable diffs.</p>'},{kind:'issues',icon:'issue',title:profile==='org'?'Opened 4 issues across 2 repositories':'Opened 4 issues in 2 repositories',body:'<div class="event-card"><button class="link" data-detail="issue">Keep the selected bookmark when browsing files</button><p>Make it easier to stay in context when moving between source and history.</p><span class="subtle">#38 · 3 comments</span></div>'}];let match=events.filter(e=>filter==='all'||e.kind===filter);if(day){const d=days().find(d=>d.date===day);match=d&&d.n?match.slice(0,1).map(e=>({...e,title:d.n+' contributions on '+day,body:'<p class="subtle">Daily drill-down preview · '+owner+'/'+repo+'</p><button class="link" data-detail="day">View sample contribution details →</button>'})):[]}
return '<section class="timeline-section"><div class="section-heading"><h2>'+(profile==='org'?'Organization activity':'Contribution activity')+'</h2><span class="subtle">'+(viewer==='public'?'Public activity':'Accessible activity')+'</span></div><div class="filters" aria-label="Activity type">'+[['all','All activity'],['changesets','Changesets'],['pulls','Pull requests'],['issues','Issues'],['reviews','Reviews']].map(([k,l])=>'<button data-filter="'+k+'" aria-pressed="'+(filter===k)+'">'+l+'</button>').join('')+'</div><div class="month">'+(day||(year===2026?'October':'December')+' '+year)+'</div>'+ (match.length?match.map(e=>'<article class="event"><span class="event-icon">'+icon(e.icon)+'</span><time>'+(day||(year===2026?'Oct':'Dec')+' 26')+'</time><h3 class="event-title">'+e.title+'</h3>'+e.body+'</article>').join(''):'<div class="empty">No contributions for this day and activity filter.</div>')+(expanded&&!day?'<div class="month">'+(year===2026?'September':'November')+' '+year+'</div><article class="event"><span class="event-icon">'+icon('repo')+'</span><h3 class="event-title">'+(profile==='org'?'Welcomed a new repository':'Created a repository')+'</h3><button class="link" data-repo="hg-toolkit">'+owner+'/hg-toolkit</button><p class="subtle">A new home for reusable Mercurial tools.</p></article>':'')+(!day?'<button class="btn full" id="more-activity">'+(expanded?'Show less activity':'Show more activity')+'</button>':'')+'</section>'}
function renderReadme(){let d=data[profile],visible=readmeMode==='present'||readmeMode==='private'&&viewer==='member';$('#readme-panel').hidden=!visible;$('#readme-restore').hidden=visible;$('#readme-path').textContent=d.repo+' / '+d.path;$('#readme-mode').value=readmeMode;$('#readme-body').innerHTML=profile==='user'?'<div class="eyebrow">HELLO, I’M '+d.name.split(' ')[0].toUpperCase()+'</div><h2>Good tools should get out of your way.</h2><p>I build self-hosted software that makes everyday work a little simpler. Currently working on <strong>Hgs</strong>: a friendly home for Mercurial repositories, issues, and code review.</p><p>I care about clear interfaces, reliable systems, and making <code>hg push</code> feel effortless.</p><div class="readme-links"><button class="link" data-repo="Hgs">Explore Hgs →</button><button class="link" data-profile="org">Meet Mercury Labs →</button><button class="link" data-source="true">View README source</button></div>':'<div class="eyebrow">WELCOME TO MERCURY LABS</div><h2>A home for people who like building things.</h2><p>We’re a small team making practical, open tools for developers. Our projects focus on <strong>Mercurial, self-hosting, and thoughtful collaboration.</strong></p><p>Start with our repositories, explore an issue, or send a pull request. Good ideas are welcome here.</p><div class="readme-links"><button class="link" data-tab="repositories">Find a project →</button><button class="link" data-tab="people">Meet the contributors →</button><button class="link" data-source="true">View README source</button></div>'}
function renderContent(){let body='';if(tab==='overview')body='<div class="two-col"><div><div class="section-heading"><h2>'+(profile==='user'?'Repositories':'Featured repositories')+'</h2><button class="link" data-tab="repositories">View all →</button></div><div class="repo-list">'+repoRows(2)+'</div>'+calendar()+timeline()+'</div>'+side()+'</div>';if(tab==='activity')body='<div class="two-col"><div>'+calendar()+timeline()+'</div>'+side()+'</div>';if(tab==='repositories')body='<div class="section-heading"><h2>'+(profile==='user'?'Repositories':'Organization repositories')+'</h2><span class="subtle">'+repos().length+' visible repositories</span></div><input class="search-input" id="repo-search" placeholder="Find a repository…" aria-label="Find a repository"><div class="repo-list" id="repo-results">'+repoRows()+'</div>';if(tab==='people')body='<div class="section-heading"><h2>People at Mercury Labs</h2><span class="subtle">Public members</span></div><div class="people-grid">'+people()+'</div>';$('#tab-content').innerHTML=body;$('#tab-content').setAttribute('aria-labelledby','tab-'+tab);$$('[role=tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===tab);b.tabIndex=b.dataset.tab===tab?0:-1})}
function render(){let d=data[profile];document.title=d.name+' · Hgs profile preview';$('#breadcrumb').textContent=(profile==='user'?'People':'Organizations')+' / '+d.handle;$('#profile-head').innerHTML='<span class="avatar large '+(profile==='org'?'org':'')+'" title="'+(profile==='org'?'Organization logo':avatarMode==='gravatar'?'Gravatar sample fixture':avatarMode==='upload'?'Uploaded sample fixture':'Local fallback')+'">'+avatar(selectedPerson,profile==='org')+'</span><div><h1>'+d.name+'</h1><div class="handle">'+d.handle+'</div><p>'+d.bio+'</p><div class="meta"><span>'+icon('pin')+d.place+'</span><span>'+icon('clock')+d.joined+'</span>'+(profile==='org'?'<span>4 public members</span>':'')+'</div></div>'+(viewer==='member'?'<button class="btn head-action" data-demo="'+(profile==='org'?'Organization settings':'Edit profile')+'">'+(profile==='org'?'Organization settings':'Edit profile')+'</button>':'');$('#rail-avatar').innerHTML=avatar();$('#nav-avatar').innerHTML=avatar();$('#repo-count').textContent=repos().length;$('#tab-people').hidden=profile!=='org';$$('.switch [data-profile]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.profile===profile));$('#user-nav').classList.toggle('active',profile==='user'&&selectedPerson===0);$('#org-nav').classList.toggle('active',profile==='org');renderReadme();renderContent()}
function closeMenu(){document.body.classList.remove('menu-open');$('#open-nav').setAttribute('aria-expanded','false')}
function dialog(html){$('#dialog-content').innerHTML=html;$('#details-dialog').showModal()}
function help(){dialog('<h2>How contributions are counted</h2><p>This prototype proposes counting <strong>changesets, opened issues, opened pull requests, and submitted reviews</strong>. Repository creation appears in the timeline but does not add a calendar contribution.</p><p>User profiles attribute changesets through verified author-email associations. A changeset is counted once per person, even when it appears in multiple forks. Organization profiles aggregate contributions to the organization’s repositories.</p><p>Every total and entry follows the viewer’s current repository access. Public visitors see public activity only; private counts and repository names are not disclosed.</p><p>Dates use a documented calendar timezone (UTC in this preview). The sample calendar ends on October 26, 2026; historical years are complete.</p><p class="subtle">These rules are proposed for discussion. The calendar is generated sample data; monthly cards illustrate layout and are not a reconciled event ledger.</p>')}
document.addEventListener('click',e=>{const cell=e.target.closest('[data-day]'),b=e.target.closest('button');if(cell){day=cell.dataset.day;renderContent();return}if(!b)return;if(b.dataset.person!==undefined){selectedPerson=Number(b.dataset.person);data.user=memberProfiles[selectedPerson];profile='user';tab='overview';day='';filter='all';readmeMode='present';expanded=false;history.replaceState(null,'','#user/'+data.user.handle);closeMenu();render();document.querySelector('h1').setAttribute('tabindex','-1');document.querySelector('h1').focus();window.scrollTo(0,0);return}if(b.dataset.profile){profile=b.dataset.profile;if(profile==='user'){selectedPerson=0;data.user=memberProfiles[0]}tab='overview';day='';filter='all';readmeMode='present';expanded=false;history.replaceState(null,'',profile==='org'?'#organization':'#user');closeMenu();render();return}if(b.dataset.tab){tab=b.dataset.tab;closeMenu();renderContent();return}if(b.dataset.filter){filter=b.dataset.filter;renderContent();return}if(b.dataset.watch){watching.has(b.dataset.watch)?watching.delete(b.dataset.watch):watching.add(b.dataset.watch);renderContent();return}if(b.dataset.star){stars.has(b.dataset.star)?stars.delete(b.dataset.star):stars.add(b.dataset.star);renderContent();return}if(b.dataset.help){help();return}if(b.dataset.source){let d=data[profile];dialog('<h2>'+d.path+'</h2><p>'+d.repo+' · default · <code>8ac2d9e61bf4</code></p><pre>'+(profile==='org'?'# A home for people who like building things.\n\nWelcome to Mercury Labs.':'# Good tools should get out of your way.\n\nI build self-hosted software.')+'</pre><p class="subtle">Production source links use an immutable Mercurial revision and enforce repository access.</p>');return}if(b.dataset.repo){dialog('<h2>'+b.dataset.repo+'</h2><p>Repository destination preview.</p><p>In the application, this opens the authorized repository source page with its existing Watch and Star controls.</p><p class="subtle">This prototype does not connect to a live repository.</p>');return}if(b.dataset.detail){dialog('<h2>Activity detail</h2><p>Production links open the corresponding changeset, issue, or pull request after checking repository access.</p><p class="subtle">Sample event: repository navigation improvements.</p>');return}if(b.dataset.demo)dialog('<h2>'+b.dataset.demo+'</h2><p>This destination belongs to the shared application. This preview focuses on profiles and does not change account settings or server data.</p>');if(b.id==='more-activity'){expanded=!expanded;renderContent()}if(b.id==='clear-day'){day='';renderContent()}});
$('#viewer').onchange=e=>{viewer=e.target.value;day='';render()};$('#avatar-mode').onchange=e=>{avatarMode=e.target.value;render()};$('#readme-mode').onchange=e=>{readmeMode=e.target.value;renderReadme()};$('#restore-readme').onclick=()=>{readmeMode='present';renderReadme()};$('#close-dialog').onclick=()=>$('#details-dialog').close();$('#open-nav').onclick=()=>{document.body.classList.add('menu-open');$('#open-nav').setAttribute('aria-expanded','true');$('#close-nav').focus()};$('#close-nav').onclick=()=>{closeMenu();$('#open-nav').focus()};$('#nav-overlay').onclick=closeMenu;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const list=$$('[role=tab]').filter(b=>!b.hidden),i=list.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;tab=list[next].dataset.tab;renderContent();list[next].focus()}});
document.addEventListener('change',e=>{if(e.target.id==='year'){year=Number(e.target.value);day='';expanded=false;renderContent()}if(e.target.id==='day-picker'){day=e.target.value;renderContent()}});
document.addEventListener('input',e=>{if(e.target.id==='repo-search'){const q=e.target.value.toLowerCase();$$('#repo-results .repo-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));if(!$$('#repo-results .repo-row').some(r=>!r.hidden)){if(!$('#repo-empty'))$('#repo-results').insertAdjacentHTML('beforeend','<p class="empty" id="repo-empty">No matching repositories.</p>')}else $('#repo-empty')?.remove()}});
render();
